package main

import "fmt"

type Counter struct {
	value int
}

func (c *Counter) Increment() {
	c.value++
}

func (c *Counter) Reset() {
	c.value = 0
}

func (c Counter) Value() int {
	return c.value
}

func main() {
	c := Counter{value: 10}
	fmt.Println("Start:", c.Value())
	c.Increment()
	c.Increment()
	fmt.Println("After increment:", c.Value())
	c.Reset()
	fmt.Println("After reset:", c.Value())
}

